#define main original_d2_benchmark_main
#include "benchmark_original_d2_basic_vs_chud.c"
#undef main

/*
 * Accelerated comparison only.
 *
 * D2 uses a balanced exact product tree in the quadratic ring generated by
 * x = H2/J, where x^2 + H1*x + H2 = 0.  This is the direct analogue of
 * Chudnovsky binary splitting: the tree topology is unchanged, while scalar
 * integer numerators are replaced by degree-2 algebraic numerators.
 *
 * The tree carries the common denominator Q, the ratio product P, the partial
 * hypergeometric sum S, and its theta-weighted sum U = sum n*t_n.  No modular
 * polynomial, no (z,u,v) transport, and no repeated modular Newton solve is
 * used.
 */

typedef struct {
    mpz_t a;
    mpz_t b;
} d2_ring_t;

typedef struct {
    mpz_t q;
    d2_ring_t p;
    d2_ring_t s;
    d2_ring_t u;
} d2_seg_t;

static void d2_ring_init(d2_ring_t *r) {
    mpz_init(r->a);
    mpz_init(r->b);
}

static void d2_ring_clear(d2_ring_t *r) {
    mpz_clear(r->a);
    mpz_clear(r->b);
}

static void d2_seg_init(d2_seg_t *s) {
    mpz_init(s->q);
    d2_ring_init(&s->p);
    d2_ring_init(&s->s);
    d2_ring_init(&s->u);
}

static void d2_seg_clear(d2_seg_t *s) {
    mpz_clear(s->q);
    d2_ring_clear(&s->p);
    d2_ring_clear(&s->s);
    d2_ring_clear(&s->u);
}

/*
 * (a+b*x)(c+d*x), x^2 = -H1*x-H2.
 * Three large products are used for the bilinear part; products by H1/H2
 * have one fixed ~100-bit operand.
 */
static void d2_ring_mul(d2_ring_t *out,
                        const d2_ring_t *x,
                        const d2_ring_t *y,
                        const mpz_t h1,
                        const mpz_t h2,
                        mpz_t m0,
                        mpz_t m1,
                        mpz_t m2,
                        mpz_t t0,
                        mpz_t t1) {
    mpz_mul(m0, x->a, y->a);
    mpz_mul(m1, x->b, y->b);

    mpz_add(t0, x->a, x->b);
    mpz_add(t1, y->a, y->b);
    mpz_mul(m2, t0, t1);

    mpz_mul(t0, h2, m1);
    mpz_sub(out->a, m0, t0);

    mpz_sub(m2, m2, m0);
    mpz_sub(m2, m2, m1);
    mpz_mul(t0, h1, m1);
    mpz_sub(out->b, m2, t0);
}

static void d2_leaf(d2_seg_t *out,
                    unsigned long n,
                    const mpz_t h2) {
    mpz_t num, den, g;
    mpz_inits(num, den, g, NULL);

    /* r_n = t_{n+1}/t_n = A_n*1728*x / (72*(n+1)^3*H2). */
    mpz_set_ui(num, 6UL * n + 1UL);
    mpz_mul_ui(num, num, 2UL * n + 1UL);
    mpz_mul_ui(num, num, 6UL * n + 5UL);
    mpz_mul_ui(num, num, 1728UL);

    mpz_set_ui(den, n + 1UL);
    mpz_mul_ui(den, den, n + 1UL);
    mpz_mul_ui(den, den, n + 1UL);
    mpz_mul_ui(den, den, 72UL);
    mpz_mul(den, den, h2);

    /* Cancel the scalar part before it enters the tree. */
    mpz_gcd(g, num, den);
    mpz_divexact(num, num, g);
    mpz_divexact(out->q, den, g);

    mpz_set_ui(out->p.a, 0UL);
    mpz_set(out->p.b, num);

    mpz_set(out->s.a, out->q);
    mpz_set_ui(out->s.b, 0UL);

    mpz_mul_ui(out->u.a, out->q, n);
    mpz_set_ui(out->u.b, 0UL);

    mpz_clears(num, den, g, NULL);
}

static void d2_bs_build(d2_seg_t *out,
                        unsigned long a,
                        unsigned long b,
                        const mpz_t h1,
                        const mpz_t h2) {
    if (b - a == 1UL) {
        d2_leaf(out, a, h2);
        return;
    }

    unsigned long m = a + (b - a) / 2UL;
    d2_seg_t left, right;
    d2_seg_init(&left);
    d2_seg_init(&right);
    d2_bs_build(&left, a, m, h1, h2);
    d2_bs_build(&right, m, b, h1, h2);

    mpz_t m0, m1, m2, t0, t1;
    mpz_inits(m0, m1, m2, t0, t1, NULL);
    d2_ring_t rs, ru;
    d2_ring_init(&rs);
    d2_ring_init(&ru);

    mpz_mul(out->q, left.q, right.q);

    d2_ring_mul(&out->p, &left.p, &right.p,
                h1, h2, m0, m1, m2, t0, t1);

    d2_ring_mul(&rs, &left.p, &right.s,
                h1, h2, m0, m1, m2, t0, t1);
    mpz_mul(out->s.a, left.s.a, right.q);
    mpz_add(out->s.a, out->s.a, rs.a);
    mpz_mul(out->s.b, left.s.b, right.q);
    mpz_add(out->s.b, out->s.b, rs.b);

    d2_ring_mul(&ru, &left.p, &right.u,
                h1, h2, m0, m1, m2, t0, t1);
    mpz_mul(out->u.a, left.u.a, right.q);
    mpz_add(out->u.a, out->u.a, ru.a);
    mpz_mul(out->u.b, left.u.b, right.q);
    mpz_add(out->u.b, out->u.b, ru.b);

    d2_ring_clear(&rs);
    d2_ring_clear(&ru);
    mpz_clears(m0, m1, m2, t0, t1, NULL);
    d2_seg_clear(&left);
    d2_seg_clear(&right);
}

static void d2_eval_ring(mpf_t out,
                         const d2_ring_t *r,
                         const mpz_t q,
                         const mpf_t x,
                         mp_bitcnt_t bits) {
    mpf_t a, b, fq;
    mpf_init2(a, bits);
    mpf_init2(b, bits);
    mpf_init2(fq, bits);
    mpf_set_z(a, r->a);
    mpf_set_z(b, r->b);
    mpf_mul(b, b, x);
    mpf_add(a, a, b);
    mpf_set_z(fq, q);
    mpf_div(out, a, fq);
    mpf_clears(a, b, fq, NULL);
}

static int d2_bs_pi(uint64_t digits,
                    uint64_t guard,
                    const char *path,
                    double *seconds,
                    unsigned long *terms_out,
                    mp_bitcnt_t extra_bits) {
    double t0 = now_seconds();
    mp_bitcnt_t bits = rj_bits_for_decimal(digits, guard) + extra_bits;

    const long double digits_per_term =
        24.95589965765426673091470594098813130578L;
    unsigned long terms =
        (unsigned long)ceill(((long double)digits + (long double)guard + 30.0L) /
                            digits_per_term) + 2UL;

    mpz_t h1, h2, disc, tmpz;
    mpz_inits(h1, h2, disc, tmpz, NULL);
    if (mpz_set_str(h1, D2_H1, 10) != 0 ||
        mpz_set_str(h2, D2_H2, 10) != 0) {
        mpz_clears(h1, h2, disc, tmpz, NULL);
        return 0;
    }

    d2_seg_t tree;
    d2_seg_init(&tree);
    d2_bs_build(&tree, 0UL, terms, h1, h2);

    /* Stable small embedding x = H2/J = -2 H2/(H1+sqrt(H1^2-4H2)). */
    mpz_mul(disc, h1, h1);
    mpz_mul_ui(tmpz, h2, 4UL);
    mpz_sub(disc, disc, tmpz);

    mpf_t fh1, fh2, fdisc, root, x, F, T, y, v, z, alpha, beta,
          K, tmp, inv_pi, pi;
    mpf_init2(fh1, bits);   mpf_init2(fh2, bits);
    mpf_init2(fdisc, bits); mpf_init2(root, bits);
    mpf_init2(x, bits);     mpf_init2(F, bits);
    mpf_init2(T, bits);     mpf_init2(y, bits);
    mpf_init2(v, bits);     mpf_init2(z, bits);
    mpf_init2(alpha, bits); mpf_init2(beta, bits);
    mpf_init2(K, bits);     mpf_init2(tmp, bits);
    mpf_init2(inv_pi, bits);mpf_init2(pi, bits);

    mpf_set_z(fh1, h1);
    mpf_set_z(fh2, h2);
    mpf_set_z(fdisc, disc);
    mpf_sqrt(root, fdisc);
    mpf_add(tmp, fh1, root);
    mpf_mul_ui(x, fh2, 2UL);
    mpf_neg(x, x);
    mpf_div(x, x, tmp);

    d2_eval_ring(F, &tree.s, tree.q, x, bits);
    d2_eval_ring(T, &tree.u, tree.q, x, bits);

    mpf_div(y, x, fh2);
    if (!tiny_quadratic_root(D2_L1, D2_L2, v, bits)) {
        return 0;
    }

    mpf_mul_ui(z, y, 1728UL);
    mpf_ui_sub(tmp, 1UL, z);
    mpf_mul(tmp, tmp, v);
    mpf_mul_ui(tmp, tmp, 427UL);
    mpf_div(alpha, y, tmp);
    mpf_ui_sub(beta, 1UL, alpha);

    mpf_set_ui(K, 427UL);
    mpf_sqrt(K, K);
    mpf_div_ui(K, K, 6UL);
    mpf_ui_sub(tmp, 1UL, z);
    mpf_sqrt(tmp, tmp);
    mpf_mul(K, K, tmp);

    mpf_mul(inv_pi, beta, F);
    mpf_mul_ui(tmp, T, 6UL);
    mpf_add(inv_pi, inv_pi, tmp);
    mpf_mul(inv_pi, inv_pi, K);
    mpf_ui_div(pi, 1UL, inv_pi);

    int ok = write_pi(path, pi, digits);
    if (seconds) *seconds = now_seconds() - t0;
    if (terms_out) *terms_out = terms;

    mpf_clears(fh1, fh2, fdisc, root, x, F, T, y, v, z, alpha, beta,
               K, tmp, inv_pi, pi, NULL);
    d2_seg_clear(&tree);
    mpz_clears(h1, h2, disc, tmpz, NULL);
    return ok;
}

static int run_d2_bs_case(uint64_t digits) {
    const uint64_t guard = 192ULL;
    char ref_path[256], d2_path[256];
    snprintf(ref_path, sizeof(ref_path), "build/d2bs_ref_%llu.txt",
             (unsigned long long)digits);
    snprintf(d2_path, sizeof(d2_path), "build/d2bs_%llu.txt",
             (unsigned long long)digits);

    double tref = 0.0, td2 = 0.0;
    unsigned long nref = 0UL, nd2 = 0UL;

    if (!chud_bs_pi(digits, guard, ref_path, &tref, &nref)) return 0;

    /* First try the same working precision as the Chudnovsky reference. */
    if (!d2_bs_pi(digits, guard, d2_path, &td2, &nd2, 0UL)) return 0;
    int eq = files_equal(ref_path, d2_path);

    printf("%llu,%.9f,%lu,%.9f,%lu,%.6f,%d\n",
           (unsigned long long)digits,
           tref, nref,
           td2, nd2,
           td2 / tref,
           eq);
    fflush(stdout);
    return eq;
}

int main(int argc, char **argv) {
    printf("digits,chud_bs_seconds,chud_terms,d2_bs_seconds,d2_terms,d2_over_chud_bs,equal\n");
    if (argc <= 1) {
        const uint64_t defaults[] = {1000ULL, 10000ULL, 30000ULL, 100000ULL, 200000ULL};
        for (size_t i = 0; i < sizeof(defaults) / sizeof(defaults[0]); ++i) {
            if (!run_d2_bs_case(defaults[i])) return 1;
        }
        return 0;
    }
    for (int i = 1; i < argc; ++i) {
        uint64_t digits = strtoull(argv[i], NULL, 10);
        if (digits == 0ULL || !run_d2_bs_case(digits)) return 1;
    }
    return 0;
}
